const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Polygon([[
        [140.20, -6.45],
        [140.40, -6.45],
        [140.40, -6.65],
        [140.20, -6.65],
        [140.20, -6.45]
    ]]); // Area near Banamepe, Papua, Indonesia

    // Using Hansen Global Forest Change dataset for forest cover analysis.
    // It's a single image with bands for tree cover in 2000 and loss year.
    const hansen = ee.Image('UMD/hansen/global_forest_change_2021_v1_9');

    // Define forest as pixels with tree cover greater than 30% in the year 2000.
    const treeCoverThreshold = 30;
    const treeCover2000 = hansen.select('treecover2000');
    const forest2000Mask = treeCover2000.gt(treeCoverThreshold);

    // Get the loss year band. Values are 1-21 (for 2001-2021), 0 for no loss.
    const lossYear = hansen.select('lossyear');

    // 2. Data Acquisition & Processing
    // Calculate forest cover for the end of 2002.
    // This is the 2000 forest minus loss that occurred in 2001 and 2002 (lossyear 1 and 2).
    const forestLoss_up_to_2002 = lossYear.gt(0).and(lossYear.lte(2));
    const forest2002 = forest2000Mask.and(forestLoss_up_to_2002.not());

    // Calculate forest cover for the end of 2019.
    // This is the 2000 forest minus loss that occurred up to and including 2019 (lossyear 1 to 19).
    const forestLoss_up_to_2019 = lossYear.gt(0).and(lossYear.lte(19));
    const forest2019 = forest2000Mask.and(forestLoss_up_to_2019.not());

    const scale = 1000; // Use a coarse scale to avoid timeouts.

    // Calculate the area of forest for each period.
    // .multiply(ee.Image.pixelArea()) calculates area for each forested pixel.
    // reduceRegion sums up these areas.
    const area2002 = forest2002.multiply(ee.Image.pixelArea()).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    });

    const area2019 = forest2019.multiply(ee.Image.pixelArea()).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    });

    // Check for calculation failures
    const forestSqKm2002 = ee.Number(area2002.get('treecover2000')).divide(1e6);
    const forestSqKm2019 = ee.Number(area2019.get('treecover2000')).divide(1e6);

    const forestVal2002 = forestSqKm2002.getInfo();
    const forestVal2019 = forestSqKm2019.getInfo();

    // The Hansen dataset is a single global image, so C1 is not applicable.
    // We check for valid pixels by seeing if any forest was detected at all.
    if (forestVal2002 === null || forestVal2019 === null) {
        console.log("Calculation failed, result is null.");
        console.log("A"); //C3
        return;
    }

    if (forestVal2002 === 0 && forestVal2019 === 0) {
        console.log("No forest cover (>30%) detected in the region for the baseline year 2000.");
        console.log("B"); //C2
        return;
    }

    // 3. Validation & Final Answer
    console.log(`Forest Cover End of 2002 (sq km): ${forestVal2002.toFixed(2)}`);
    console.log(`Forest Cover End of 2019 (sq km): ${forestVal2019.toFixed(2)}`);

    if (forestVal2019 < forestVal2002) {
        console.log("Forest cover decreased.");
        console.log("A");
    } else {
        console.log("Forest cover did not decrease.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during Earth Engine initialization or analysis.");
        console.error(e);
        console.log("D");
    }
}

initEE();
